/* @Category(typeof(NightlyCategory)) */
public class DebuggerStaticMappingProviderTest : AbstractGhidraHeadedDebuggerTest {
	protected DebuggerStaticMappingPlugin mappingsPlugin;
	protected DebuggerStaticMappingProvider mappingsProvider;

	protected TraceStaticMappingManager manager;

	/* @Before */
	public void setUpStaticMappingsProviderTest()
    {
		mappingsPlugin = addPlugin(tool, typeof(DebuggerStaticMappingPlugin));
		mappingsProvider = waitForComponentProvider(typeof(DebuggerStaticMappingProvider));

		createTrace();
		manager = tb.trace.getStaticMappingManager();
	}

	/* @Test */
	public void testActivateThenAddStaticMappingPopulatesProvider()
    {
		traceManager.openTrace(tb.trace);
		traceManager.activateTrace(tb.trace);

		using (Transaction _ = tb.startTransaction())
{
			manager.add(tb.range(0xdeadbeef, 0xdeadbeef + 0xff), Lifespan.nowOn(0),
				new URI("ghidra://static").toURL(), "DEADBEEF");
		}
		waitForDomainObject(tb.trace);

		List<StaticMappingRow> displayed = mappingsProvider.mappingTableModel.getModelData();
		assertEquals(1, displayed.size());
		StaticMappingRow record = displayed.get(0);
		assertEquals(tb.addr(0xdeadbeef), record.getTraceAddress());
		assertEquals(new URI("ghidra://static").toURL(), record.getStaticProgramURL());
		assertEquals("DEADBEEF", record.getStaticAddress());
		assertEquals(0x100, record.getLength());
	}

